const items = $input.all();

// Séparer locataires et virements
const locataires = items.filter(item => item.json.nom && item.json.loyer);
const virements = items.filter(item => item.json.Libelle && item.json.Credit);

// Fonction de distance de Levenshtein
function levenshteinDistance(str1, str2) {
  const m = str1.length;
  const n = str2.length;
  const dp = Array(m + 1).fill().map(() => Array(n + 1).fill(0));
  for (let i = 0; i <= m; i++) dp[i][0] = i;
  for (let j = 0; j <= n; j++) dp[0][j] = j;
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      dp[i][j] = str1[i - 1] === str2[j - 1]
        ? dp[i - 1][j - 1]
        : 1 + Math.min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]);
    }
  }
  return dp[m][n];
}

// Normalisation d'une chaîne
function normalizeString(str) {
  return (str || '').toString().toUpperCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^A-Z0-9]/g, '');
}

// Extraction de noms depuis un libellé
function extractNamesFromLibelle(libelle) {
  if (!libelle) return [];
  const cleaned = libelle.toUpperCase();
  const patterns = [
    /VIR\s+(?:M|MME|MLLE)?\s*([A-Z\-\s]+?)(?:\s+\d|$)/i,
    /VIR\s+INST\s+(?:M|MME|MLLE)?\s*([A-Z\-\s]+?)(?:\s+\d|$)/i,
    /(?:DE|PAR)\s+(?:M|MME|MLLE)?\s*([A-Z\-\s]+?)(?:\s+\d|$)/i,
  ];
  const names = [];
  for (const pattern of patterns) {
    const match = cleaned.match(pattern);
    if (match && match[1]) {
      const extracted = match[1].trim();
      names.push(extracted);
      names.push(...extracted.split(/\s+/).filter(w => w.length > 2));
    }
  }
  const virSplit = cleaned.split(/VIR\s+(?:M|MME|MLLE|INST)?\s*/);
  if (virSplit.length > 1) {
    const afterVir = virSplit[1];
    const words = afterVir.split(/\s+/).filter(w => w.length > 2 && !/^\d+$/.test(w)).slice(0, 3);
    names.push(...words);
  }
  return [...new Set(names)];
}

// Similarité entre deux chaînes
function calculateStringSimilarity(str1, str2) {
  const s1 = normalizeString(str1);
  const s2 = normalizeString(str2);
  if (!s1 || !s2) return 0;
  if (s1 === s2) return 100;
  if (s1.includes(s2) || s2.includes(s1)) return 90;
  const distance = levenshteinDistance(s1, s2);
  const maxLen = Math.max(s1.length, s2.length);
  return Math.round(((maxLen - distance) / maxLen) * 100);
}

// Calcul de matching
function calculateMatch(locataire, virement) {
  const attendu = parseFloat(locataire.loyer?.toString().replace(',', '.')) || 0;
  const recu = parseFloat(virement.Credit?.toString().replace(',', '.')) || 0;

  let montantScore = 0;
  if (attendu === recu) montantScore = 48;
  else {
    const diff = Math.abs(attendu - recu);
    const pct = (diff / attendu) * 100;
    if (pct <= 1) montantScore = 45;
    else if (diff <= 5) montantScore = 40;
    else if (diff <= 10) montantScore = 30;
    else if (pct <= 5) montantScore = 20;
  }

  const noms = extractNamesFromLibelle(virement.Libelle);
  let bestNameSimilarity = 0;
  for (const name of noms) {
    const sim = calculateStringSimilarity(locataire.nom, name);
    if (sim > bestNameSimilarity) bestNameSimilarity = sim;
  }

  let nomScore = 0;
  if (bestNameSimilarity >= 90) nomScore = 55;
  else if (bestNameSimilarity >= 80) nomScore = 45;
  else if (bestNameSimilarity >= 70) nomScore = 35;
  else if (bestNameSimilarity >= 60) nomScore = 25;
  else if (bestNameSimilarity >= 50) nomScore = 15;

  const totalScore = montantScore + nomScore;

  return {
    lieu: locataire.lieu || null,
    nom: locataire.nom,
    loyer: attendu,
    id: virement.id,
    dateValeur: virement['Date valeur'],
    libelle: virement.Libelle,
    credit: recu,
    score: totalScore,
    bestNameSimilarity,
    montantScore,
    nomScore,
  };
}

// Appliquer le fuzzy matching pour chaque locataire
const output = locataires.map(l => {
  const scores = virements.map(v => calculateMatch(l.json, v.json));
  scores.sort((a, b) => b.score - a.score); // Tri décroissant
  return { json: scores[0] }; // Meilleur match
});

return output;

