const rows = $input.all(); // Récupère tous les items

const result = rows
  .map(({ json }) => {
    const nom = json['NOM'];
    const loyer = json['LOYER'];
    const lieu = json['LIEU'];

    // Vérifie que les données sont valides
    if (nom && !isNaN(loyer)) {
      return {
        nom: nom.trim(),
        loyer: parseFloat(loyer.toString().replace(',', '.')),
        lieu: (lieu || '').toString().trim()
      };
    } else {
      return null;
    }
  })
  .filter(Boolean) // Supprime les lignes nulles
  .map(data => ({ json: data }));

return result;

return items
  .filter(item => {
    const credit = item.json['Credit'];
    const libelle = (item.json['Libelle'] || '').toUpperCase();

    // Inclut uniquement les lignes avec un crédit défini
    // Et dont le libellé ne contient ni "PLACEHOLDER_A" ni "PLACEHOLDER_B"
    return credit &&
           credit !== '[empty]' &&
           !libelle.includes('PLACEHOLDER_A') &&
           !libelle.includes('PLACEHOLDER_B');
  })
  .map((item, index) => {
    const { ['Date valeur']: dateVal, Libelle, Credit } = item.json;
    return {
      json: {
        id: index,
        'Date valeur': dateVal,
        'Libelle': Libelle,
        'Credit': Credit
      }
    };
  });

