const [existing, incoming] = $input.all().map(item => item.json);

// Si pas de nom, on ne peut pas continuer
if (!incoming.nom) {
  throw new Error("Champ 'nom' manquant dans la ligne entrante");
}

// Préfixe de colonnes à mettre à jour : JULLIOT_montant, etc.
const prefix = incoming.nom.trim().toUpperCase().replace(/\s/g, '');

// Mise à jour des champs dynamiques
existing[`${prefix}_montant`] = incoming.credit || '';
existing[`${prefix}_libelle`] = incoming.libelle || '';
existing[`${prefix}_date`] = incoming.dateValeur || '';

// Mise à jour du mois si absent
if (!existing.mois && incoming.dateValeur) {
  const [jour, mois, annee] = incoming.dateValeur.split('/');
  const moisStr = new Date(`${annee}-${mois}-${jour}`)
    .toLocaleDateString('fr-FR', { month: 'long' })
    .toLowerCase();
  existing.mois = moisStr;
}

// Renvoi d'un seul objet prêt à être écrit dans la feuille
return [{ json: existing }];

