function safeLength(nodeName) {
  try {
    return $items(nodeName).length || 0;
  } catch (e) {
    return 0;
  }
}

// Récupération des données
const nbLocatairesTotal = safeLength("expected_rent_parsing");
const nbIncertains = safeLength("incertain compteur");
const nbLocatairesTries = nbLocatairesTotal - nbIncertains;

// Horodatage
const now = new Date();
const timestamp = now.toLocaleString('fr-FR');

// Durée d'exécution
const startedAtRaw = $execution?.startedAt;
const start = startedAtRaw ? new Date(startedAtRaw) : null;
const duration = start ? ((now - start) / 1000).toFixed(2) : null;

return [
  {
    json: {
      nbLocatairesTotal,
      nbIncertains,
      nbLocatairesTries,
      timestamp,
      duration
    }
  }
];

const rows = $input.all().map(item => item.json);

// Générer les en-têtes automatiquement
const headers = Object.keys(rows[0]);

// Construire l'en-tête du tableau HTML
let html = `<table border="1" cellpadding="5" cellspacing="0" style="border-collapse: collapse;">`;
html += `<tr>${headers.map(h => `<th>${h}</th>`).join('')}</tr>`;

// Construire les lignes du tableau
for (const row of rows) {
  html += `<tr>${headers.map(h => `<td>${row[h] ?? ''}</td>`).join('')}</tr>`;
}

html += `</table>`;

// Génère les 2 items de sortie
return [
  {
    json: {
      htmlTable: html
    }
  },
  {
    json: {
      locataireTotal: rows.length
    }
  }
];
